  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C01"],
      "claim": "PET imaging in pigs after intravenous administration of [11C]GSK931145 showed good brain penetration and heterogeneous distribution consistent with GlyT-1 localization, directly demonstrating meaningful CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "In Wistar rats, a single systemic injection of leucine produced brain concentrations of 1-2 µmol/g at 60 minutes, showing that leucine readily crosses the blood-brain barrier.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "In humans with tuberculous meningitis, intravenous amoxycillin achieved CSF concentrations of 8-93% (mean 48.5%) of serum concentrations, demonstrating meaningful CNS access after systemic administration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Rat pharmacokinetic studies showed that AHN 1-055, AHN 2-003, AHN 2-005, and JHW 007 readily and rapidly crossed the blood-brain barrier, with brain-to-plasma ratios equal to or greater than 2-fold that of cocaine.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "In healthy male subjects, LY450108 produced quantifiable CSF concentrations with a plasma:CSF ratio of 44:1, confirming penetration into the central compartment.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "All available experimental records consistently demonstrate BBB permeability and meaningful CNS access across multiple species, routes, and chemotypes; no record indicates restricted brain exposure. Therefore the prediction is pass, with moderate confidence due to the absence of query-specific direct measurements.",
